   214→                color={isAbstractOpen ? 'cyan.400' : useColorModeValue('gray.600', 'gray.400')}
   215→                fontSize="xs"
   216→                fontFamily="mono"
   217→                transition="all 0.15s"
   218→                _hover={{ borderColor: 'cyan.400', color: 'cyan.400' }}
   219→                onClick={onToggleAbstract}
   220→              >
   221→                <DynamicIcon name="FaChevronRight" boxSize={2.5} style={{ transform: isAbstractOpen ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s' }} />
   222→                <Text>{t('about.abstract')}</Text>
   223→              </HStack>
   224→            )}
   225→          </HStack>
   226→        </VStack>
   227→      </Flex>
   228→
   229→      {/* Abstract - full width below */}
   230→      {pub.abstract && (
   231→        <Collapse in={isAbstractOpen} animateOpacity>
   232→          <Box
   233→            mt={4}
   234→            p={4}
   235→            bg={useColorModeValue('gray.50', 'gray.900')}
   236→            borderRadius="md"
   237→            borderLeft="2px solid"
   238→            borderLeftColor="cyan.400"
   239→          >
   240→            <Text fontSize={["xs", "sm"]} lineHeight="tall" color={useColorModeValue('gray.600', 'gray.400')}>
   241→              {pub.abstract}
   242→            </Text>
   243→            {pub.keywords && (
   244→              <HStack mt={3} spacing={1.5} flexWrap="wrap">
   245→                {pub.keywords.map((keyword: string) => (
   246→                  <Text
   247→                    key={keyword}
   248→                    fontSize="2xs"
   249→                    fontFamily="mono"
   250→                    color={useColorModeValue('gray.500', 'gray.500')}
   251→                    px={1.5}
   252→                    py={0.5}
   253→                    bg={useColorModeValue('gray.100', 'gray.800')}
   254→                    borderRadius="sm"
   255→                  >
   256→                    {keyword}
   257→                  </Text>
   258→                ))}
   259→              </HStack>
   260→            )}
   261→          </Box>
   262→        </Collapse>
   263→      )}
   264→
   265→      <Modal isOpen={isImageOpen} onClose={onImageClose} size="4xl" isCentered>
   266→        <ModalOverlay />
   267→        <ModalContent bg="transparent" boxShadow="none">
   268→          <ModalCloseButton color={useColorModeValue('gray.700', 'gray.200')} />
   269→          <ModalBody p={0} display="flex" alignItems="center" justifyContent="center">
   270→            <Image
   271→              src={pub.featuredImage}
   272→              alt={`${pub.title} large preview`}
   273→              maxH="80vh"
   274→              maxW="90vw"
   275→              objectFit="contain"
   276→              borderRadius="lg"
   277→              bg={useColorModeValue('white', 'gray.900')}
   278→              p={4}
   279→            />
   280→          </ModalBody>
   281→        </ModalContent>
   282→      </Modal>
   283→    </Box>
   284→  );
   285→};
   286→
   287→function About() {
   288→  const { t } = useTranslation();
   289→  const { research, experience, news, about, publications, siteConfig } = useLocalizedData();
   290→  // Sort news items by date (newest first)
   291→  const sortedNews = useMemo(() => {
   292→    return [...news].sort((a, b) => {
   293→      if (!a.sortDate && !b.sortDate) return 0;
   294→      if (!a.sortDate) return 1;
   295→      if (!b.sortDate) return -1;
   296→      return b.sortDate.localeCompare(a.sortDate);
