                              {/* Dot */}
                              <Box flexShrink={0} mt="6px">
                                <Box
                                  w="14px"
                                  h="14px"
                                  borderRadius="full"
                                  border="2px solid"
                                  borderColor={index === about.journeyPhases!.length - 1 ? 'cyan.400' : useColorModeValue('gray.300', 'gray.600')}
                                  bg={index === about.journeyPhases!.length - 1 ? 'cyan.400' : useColorModeValue('white', 'gray.800')}
