## 第四步：创建首页组件 `Home`

首先，在 `src` 文件夹中创建一个名为 `components` 的文件夹，然后在里面创建 `Home.tsx`：

```tsx
// ─────────────────────────────────────────────────────────
// Home.tsx - 首页组件
// 显示：个人简介、头像、联系方式等基本信息
// ─────────────────────────────────────────────────────────

// 从 Chakra UI 导入需要的组件
// Box：最基本的容器，相当于 div
// VStack：垂直排列的容器，items 垂直堆叠
// Heading：标题组件，相当于 h1, h2, h3...
// Text：文本组件，相当于 p 或 span
// Image：图片组件
// HStack：水平排列的容器，items 水平排列
// Container：响应式容器，限制最大宽度
import { 
  Box, 
  VStack, 
  Heading, 
  Text, 
  Image, 
  HStack, 
  Container, 
  Link,
  Flex,
  Avatar,
  useColorModeValue
} from '@chakra-ui/react'

// 定义首页组件
// const Home: React.FC = () => { ... }
// 解释：
// - const: 声明一个常量
// - Home: 组件名（大写开头，React 组件的命名规范）
// - React.FC: TypeScript 类型，表示 React 函数组件
function Home() {
  // ─────────────────────────────────────────────────
  // useColorModeValue 是 Chakra UI 的 Hook
  // 作用：根据当前颜色模式（浅色/深色）返回不同的值
  // 参数：(浅色时的值, 深色时的值)
  // ─────────────────────────────────────────────────

  // 背景色：浅色模式用白色，深色模式用深灰色
  const bgColor = useColorModeValue('white', 'gray.800')

  // 文字颜色：浅色模式用深灰色，深色模式用白色
  const textColor = useColorModeValue('gray.700', 'gray.100')

  // 次要文字颜色
  const secondaryTextColor = useColorModeValue('gray.500', 'gray.400')

  // 返回 JSX（React 元素）
  return (
    // <Box> 是最基础的容器，相当于 HTML 的 div
    // 属性解释：
    // - w="full": 宽度 100%
    // - minH="100vh": 最小高度 100vh（视口高度）
    // - py={8}: padding-top 和 padding-bottom 为 8（ Chakra UI 的 spacing 系统，8 = 2rem = 32px）
    <Box w="full" minH="100vh" py={8}>

      // <Container> 是响应式容器
      // maxW="xl": 最大宽度 xl（约 1280px）
      // mx="auto": 水平外边距 auto（居中）
      <Container maxW="xl" mx="auto">

        // <VStack> 是垂直堆叠容器
        // spacing={6}: 子元素之间的间距为 6
        // align="stretch": 子元素拉伸到容器宽度
        <VStack spacing={6} align="stretch">

          {/* ─────────────────────────────────────────
              第一部分：个人简介区域
          ───────────────────────────────────────── */}

          // <Flex> 是弹性容器（类似 CSS Flexbox）
          // direction="column": 垂直方向排列（手机端默认）
          // md={{ direction: 'row' }}: 中等屏幕及以上时改为水平排列
          // gap={6}: 子元素间距为 6
          <Flex 
            direction={{ base: 'column', md: 'row' }} 
            gap={6} 
            align="center"
            // py: padding-top 和 padding-bottom
            py={8}
          >

            {/* 头像区域 */}
            {/* size="2xl": 超大头像（约 150px） */}
            {/* borderWidth: 边框宽度 */}
            {/* borderColor: 边框颜色 */}
            <Avatar 
              size="2xl" 
              name="杨思行" 
              src="/avatar.jpg"
              borderWidth="4px"
              borderColor={useColorModeValue('blue.400', 'blue.600')}
            />

            {/* 文字信息区域 */}
            {/* flex={1}: 占据剩余空间 */}
            <VStack align={{ base: 'center', md: 'start' }} spacing={3} flex={1}>

              {/* 姓名标题 */}
              {/* size="2xl": 特大标题 */}
              {/* fontWeight="bold": 加粗 */}
              <Heading size="2xl" fontWeight="bold" color={textColor}>
                杨思行
              </Heading>

              {/* 个人简介 / 副标题 */}
              {/* fontSize="xl": 大号字体 */}
              {/* color={secondaryTextColor}: 使用上面定义的次要文字颜色 */}
              <Text fontSize="xl" color={secondaryTextColor}>
                全栈开发者 | 技术爱好者 | 终身学习者
              </Text>

              {/* 个人描述 */}
              {/* fontSize="md": 中等字体 */}
              <Text fontSize="md" color={secondaryTextColor} textAlign={{ base: 'center', md: 'left' }}>
                热爱编程，专注于 Web 开发。喜欢探索新技术，
                致力于构建优雅、高效的应用程序。
              </Text>

              {/* 社交链接 */}
              {/* HStack: 水平排列 */}
              <HStack spacing={4} pt={2}>
                {/* Link: 链接组件 */}
                {/* isExternal: 点击在新标签页打开 */}
                {/* _hover: 悬停时的样式 */}
                <Link 
                  href="https://github.com" 
                  isExternal
                  color="blue.500"
                  _hover={{ color: 'blue.600', textDecoration: 'none' }}
                >
                  GitHub
                </Link>
                <Link 
                  href="mailto:example@email.com" 
                  color="blue.500"
                  _hover={{ color: 'blue.600', textDecoration: 'none' }}
                >
                  邮箱
                </Link>
              </HStack>

            </VStack>
          </Flex>

          {/* ─────────────────────────────────────────
              第二部分：技能标签（可选展示）
          ───────────────────────────────────────── */}

          {/* 技能区域标题 */}
          <Box pt={4}>
            <Heading size="md" color={textColor} mb={4}>
              技能
            </Heading>

            {/* 技能标签容器 */}
            {/* flexWrap: 允许换行 */}
            <Flex flexWrap="wrap" gap={2}>
              {/* 技能标签 */}
              {/* px: padding-left 和 padding-right */}
              {/* py: padding-top 和 padding-bottom */}
              {/* bg: 背景色 */}
              {/* borderRadius: 圆角 */}
              <Text px={3} py={1} bg="blue.50" color="blue.600" borderRadius="full" fontSize="sm">
                JavaScript
              </Text>
              <Text px={3} py={1} bg="blue.50" color="blue.600" borderRadius="full" fontSize="sm">
                TypeScript
              </Text>
              <Text px={3} py={1} bg="blue.50" color="blue.600" borderRadius="full" fontSize="sm">
                React
              </Text>
              <Text px={3} py={1} bg="blue.50" color="blue.600" borderRadius="full" fontSize="sm">
                Node.js
              </Text>
              <Text px={3} py={1} bg="blue.50" color="blue.600" borderRadius="full" fontSize="sm">
                Python
              </Text>
            </Flex>
          </Box>

        </VStack>
      </Container>
    </Box>
  )
}

// 导出组件，供其他文件使用
export default Home
```

